#include <stdio.h>

/* teste do desafio soma-das-notas — counter_protocol (03-tdd 3.9.3).
   Fase VALOR: nao ha captura de stdout aqui. O teste declara o prototipo
   da caixa do aluno, chama-a e confere o VALOR devolvido com checa_int.
   Tres turmas de notas de pontas diferentes: nenhum numero fixo devolvido
   passa nos tres cenarios. */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
int somaDasNotas(int primeira, int ultima);

SM_TEST(a_soma_da_turma_a) {
    checa_int("a soma da turma A", somaDasNotas(10, 2), 35,
              "10 + 8 + 6 + 9 + 2 da 35: as cinco gavetas entram na soma");
}

SM_TEST(a_soma_da_turma_b) {
    checa_int("a soma da turma B", somaDasNotas(3, 7), 33,
              "3 + 8 + 6 + 9 + 7 da 33: mudar as pontas muda o total");
}

SM_TEST(a_soma_com_as_pontas_em_zero) {
    checa_int("a soma com as pontas em zero", somaDasNotas(0, 0), 23,
              "com as pontas em 0 sobram as tres gavetas do meio: 8 + 6 + 9 da 23");
}

solutionCode:
int somaDasNotas(int primeira, int ultima) {
    int notas[5] = {primeira, 8, 6, 9, ultima};
    int total = 0;
    for (int i = 0; i < 5; i++) {
        total += notas[i];
    }
    return total;
}
